import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { PlanExtractionError, needsCalibration, reconcilableShapes, runPlanExtractor } from '../plans/extractor.js';

/**
 * These tests run the real Python sidecar against two drawings generated by
 * `tools/plan-extractor/make_fixtures.py` — a millimetre DXF with an Arabic label
 * and a hatched bedroom, and a 1:50 vector PDF. They are skipped only when the
 * sidecar's virtualenv is absent, never when it merely fails: a skipped test that
 * hides a broken bridge is worse than a red one.
 */

const python = fileURLToPath(new URL('../../../../tools/plan-extractor/.venv/bin/python', import.meta.url));
const fixtures = fileURLToPath(new URL('../../../../tools/plan-extractor/fixtures/', import.meta.url));
const dxf = `${fixtures}flats.dxf`;
const pdf = `${fixtures}flats.pdf`;
const available = existsSync(python) && existsSync(dxf) && existsSync(pdf);
const maybe = available ? describe : describe.skip;

maybe('plan extractor bridge', () => {
  it('reads a millimetre DXF: areas, kinds and a non-Latin label', async () => {
    const result = await runPlanExtractor({ format: 'dxf', filePath: dxf });

    expect(result.engine).toBe('ezdxf');
    expect(result.unit).toBe('mm');
    expect(result.unit_source).toBe('insunits');
    expect(result.scale_known).toBe(true);

    const flats = result.shapes.filter((shape) => shape.code.startsWith('LWPOLYLINE'));
    expect(flats.map((shape) => shape.area_sqm)).toEqual([60, 45, 18, 24.75]);

    const byArea = new Map(result.shapes.map((shape) => [shape.area_sqm, shape]));
    expect(byArea.get(60)?.label).toBe('Flat 101');
    // Arabic survives the process boundary; a JSON encoder that mangled it would
    // silently relabel every unit in Amman.
    expect(byArea.get(18)?.label).toBe('شقة 103');
    // The hatch is a bedroom, nested in flat 102 — the label follows the hint.
    expect(byArea.get(1.75)?.room_kind).toBe('bedroom');
    expect(byArea.get(24.75)?.room_kind).toBe('corridor');
  });

  it('reports the bow-tie instead of quietly turning it into area', async () => {
    const result = await runPlanExtractor({ format: 'dxf', filePath: dxf });
    expect(result.warnings.some((warning) => warning.reason === 'self_intersecting')).toBe(true);
    // The bow-tie is 17-21 m across and would have "area" 8000 * 4000 = 3.2 m² per
    // shoelace cancellation — it must not appear among the shapes at all.
    expect(result.shapes.some((shape) => shape.area_sqm === 0)).toBe(false);
  });

  it('refuses to leave points without a calibration, and converts once given one', async () => {
    const unscaled = await runPlanExtractor({ format: 'pdf', filePath: pdf });
    expect(unscaled.scale_known).toBe(false);
    expect(needsCalibration(unscaled)).toBe(true);
    expect(unscaled.shapes.every((shape) => shape.area_sqm === null)).toBe(true);
    expect(unscaled.warnings.some((warning) => warning.reason === 'scale_unknown')).toBe(true);
    expect(reconcilableShapes(unscaled)).toEqual([]);

    const scaled = await runPlanExtractor({
      format: 'pdf',
      filePath: pdf,
      calibrate: '60,60,60,626.93,10',
    });
    expect(scaled.scale_known).toBe(true);
    expect(scaled.shapes.map((shape) => shape.area_sqm).sort((a, b) => Number(b) - Number(a))).toEqual([60, 45, 18]);
    expect(scaled.shapes.map((shape) => shape.label).sort()).toEqual(['Flat 101', 'Flat 102', 'Flat 103']);
  });

  it('says DWG is unsupported instead of pretending to read it', async () => {
    await expect(runPlanExtractor({ format: 'dwg', filePath: `${fixtures}nope.dwg` })).rejects.toMatchObject({
      code: 'unsupported_format',
    });
  });

  it('surfaces a missing file as an extractor error, not a crash', async () => {
    await expect(
      runPlanExtractor({ format: 'dxf', filePath: `${fixtures}does-not-exist.dxf` }),
    ).rejects.toBeInstanceOf(PlanExtractionError);
  });
});
